SELECT id, symbol, observed_at, source_received_at, created_at, TIMESTAMPDIFF(MICROSECOND, observed_at, created_at)/1000 AS insert_minus_event_ms, price, delivery_status, outcome_reason FROM crypto_ai.market_price_event WHERE (symbol='EGLDUSDT' AND observed_at BETWEEN '2026-10-11 21:00:00' AND '2026-10-11 21:00:10') OR (symbol='XRPUSDT' AND observed_at BETWEEN '2026-10-12 03:30:03' AND '2026-10-12 03:30:05') OR (symbol='EGLDUSDT' AND observed_at BETWEEN '2026-10-11 22:43:34' AND '2026-10-11 22:43:36') OR (symbol='SHIBUSDT' AND observed_at BETWEEN '2026-10-12 07:15:05' AND '2026-10-12 07:15:44') OR (symbol='ACEUSDT' AND observed_at BETWEEN '2026-10-12 10:05:05' AND '2026-10-12 10:05:19') ORDER BY symbol, observed_at LIMIT 100;